class CampaignProgress { int experience=0, level=1, requisition=0, threat=0; String currentMissionId=''; final Set<String> completedMissions={}, unlockedMissions={'hive_sweep'}; final Map<String,int> killsByType={}; final Map<String,String> decisions={}; void beginMission(String id){currentMissionId=id;} void recordKill(String type){killsByType.update(type,(v)=>v+1,ifAbsent:()=>1);} void completeMission(String id,{int xp=0,int requisitionReward=0}){completedMissions.add(id); experience+=xp; requisition+=requisitionReward; level=1+(experience~/250); if(id=='hive_sweep') unlockedMissions.add('tomb_signal'); if(id=='tomb_signal') unlockedMissions.add('warp_ritual'); currentMissionId='';} void recordDecision(String id,String choice){decisions[id]=choice;} Map<String,dynamic> toJson()=>{'experience':experience,'level':level,'requisition':requisition,'threat':threat,'currentMissionId':currentMissionId,'completedMissions':completedMissions.toList(),'unlockedMissions':unlockedMissions.toList(),'killsByType':killsByType,'decisions':decisions}; void loadJson(dynamic raw){if(raw is! Map)return; experience=(raw['experience'] as num?)?.toInt()??0; level=(raw['level'] as num?)?.toInt()??1; requisition=(raw['requisition'] as num?)?.toInt()??0; threat=(raw['threat'] as num?)?.toInt()??0; currentMissionId=raw['currentMissionId'] as String? ?? ''; completedMissions..clear()..addAll((raw['completedMissions'] as List? ?? const []).whereType<String>()); unlockedMissions..clear()..add('hive_sweep')..addAll((raw['unlockedMissions'] as List? ?? const []).whereType<String>()); killsByType..clear(); if(raw['killsByType'] is Map) (raw['killsByType'] as Map).forEach((k,v){if(k is String&&v is num)killsByType[k]=v.toInt();}); decisions..clear(); if(raw['decisions'] is Map) (raw['decisions'] as Map).forEach((k,v){if(k is String&&v is String)decisions[k]=v;}); level=level<1?1:level; } }
